SELECT ?zone ?zlabel ?sensor ?slabel ?ref WHERE {
  ?z a brick:Zone ; brick:hasIdentifier "Zone_F3_Z01" .
  OPTIONAL { ?z rdfs:label ?zlabel }
  ?sensor brick:hasLocation ?z .
  ?sensor a ?sc .
  FILTER (YURI(?sc) ENDS WITH "TemperatureSensor" || YURI(?sensor) ENDS WITH "TemperatureSensor")
  OPTIONAL { ?sensor rdfs:label ?slabel }
  OPTIONAL { ?sensor ref:hasExternalReference ?ref }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ref }
}

SELECT ?z ?lab ?s WHERE {
  ?z a brick:HVAC_Zone .
  ?s a brick:Zone_Air_Temperature_Sensor ; brick:hasLocation ?z .
  OPTIONAL { ?z rdfs:label ?lab }
}

SELECT ?z ?zloc WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s ?p ?zloc .
  FILTER (str(?zloc) != str(""))
} LIMIT 10

SELECT ?s ?loc ?tsid WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s brick:hasLocation ?loc .
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?s ref:hasExternalReference ?tsid }
}

SELECT DISTINCT ?p WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s ?p ?o .
  FILTER (strstarts(str(?p),"http://buildgraph.org"))
}

